namespace sv_ffb80ff020cd4cefb413c0c9e14f2897.Components;

public enum ScreenSize
{
    Mobile,
    Tablet,
    Desktop
}

export function getWidth() {
    return window.innerWidth;
}

export function addResizeListener(dotNetRef) {
    const handler = () => {
        dotNetRef.invokeMethodAsync('OnBrowserResize', window.innerWidth);
    };
    window.addEventListener('resize', handler);
    return handler;
}

export function removeResizeListener(handler) {
    window.removeEventListener('resize', handler);
}

@implements IAsyncDisposable
@inject IJSRuntime JS

<CascadingValue Value="CurrentScreenSize">
    @ChildContent
</CascadingValue>

@code {
    [Parameter]
    public RenderFragment? ChildContent { get; set; }

    public ScreenSize CurrentScreenSize { get; private set; } = ScreenSize.Desktop;

    private IJSObjectReference? _module;
    private IJSObjectReference? _resizeHandler;
    private DotNetObjectReference<ScreenSizeProvider>? _dotNetRef;

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            _module = await JS.InvokeAsync<IJSObjectReference>("import", "./js/screen-size.js");
            var width = await _module.InvokeAsync<int>("getWidth");
            UpdateCategory(width);

            _dotNetRef = DotNetObjectReference.Create(this);
            _resizeHandler = await _module.InvokeAsync<IJSObjectReference>("addResizeListener", _dotNetRef);
            StateHasChanged();
        }
    }

    [JSInvokable]
    public void OnBrowserResize(int width)
    {
        var newSize = Categorize(width);
        if (newSize != CurrentScreenSize)
        {
            CurrentScreenSize = newSize;
            StateHasChanged();
        }
    }

    private void UpdateCategory(int width)
    {
        CurrentScreenSize = Categorize(width);
    }

    private static ScreenSize Categorize(int width) => width switch
    {
        < 768 => ScreenSize.Mobile,
        < 1024 => ScreenSize.Tablet,
        _ => ScreenSize.Desktop
    };

    public async ValueTask DisposeAsync()
    {
        if (_module is not null && _resizeHandler is not null)
        {
            await _module.InvokeVoidAsync("removeResizeListener", _resizeHandler);
        }
        _dotNetRef?.Dispose();
        if (_module is not null)
        {
            await _module.DisposeAsync();
        }
    }
}

